-- E) the two tattoo voucher items the client item table has and the server item table lacks
--    (cloned from the sibling 30-day voucher 810926000, names from the client Item_Org_us.tbl)
INSERT INTO item SELECT (jsonb_populate_record(NULL::item, to_jsonb(i) || jsonb_build_object('num', 810921000, 'str_name', 'Voucher of War Wings ( 30 Days )'))).*
FROM item i WHERE i.num = 810926000 AND NOT EXISTS (SELECT 1 FROM item x WHERE x.num = 810921000);
INSERT INTO item SELECT (jsonb_populate_record(NULL::item, to_jsonb(i) || jsonb_build_object('num', 810924000, 'str_name', 'Voucher of Wing of Pitch Black ( 30 Days )'))).*
FROM item i WHERE i.num = 810926000 AND NOT EXISTS (SELECT 1 FROM item x WHERE x.num = 810924000);

